import { test, expect } from '@playwright/test';

test.describe('Table Row Selection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://your-application-url.com');
  });

  test('should select all rows when header checkbox is checked', async ({ page }) => {
    const headerCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await headerCheckbox.check();

    const selectedRows = await page.getByRole('row', { selected: true }).count();
    const totalRows = await page.getByRole('row').count();

    expect(selectedRows).toBe(totalRows);
  });

  test('should deselect all rows when header checkbox is unchecked', async ({ page }) => {
    const headerCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await headerCheckbox.check();
    await headerCheckbox.uncheck();

    const selectedRows = await page.getByRole('row', { selected: true }).count();

    expect(selectedRows).toBe(0);
  });
});
